function(x=unit(.5,'npc'), y=unit(.5,'npc'), width=unit(1,'npc'), height=unit(1,'npc'), default.units='npc', just='centre', gp=gpar(), clip='inherit', xscale=c(0,1), yscale=c(0,1), angle=0, layout=NULL, layout.pos.row=NULL, layout.pos.col=NULL, name=NULL) { if (!is.unit(x)) x<-unit(x,default.units); if (!is.unit(y)) y<-unit(y,default.units); if (!is.unit(width)) width<-unit(width,default.units); if (!is.unit(height)) height<-unit(height,default.units); structure(list(x=x,y=y,width=width,height=height,just=just,gp=gp,clip=clip,xscale=xscale,yscale=yscale,angle=angle,layout=layout,row=layout.pos.row,col=layout.pos.col,name=name),class='viewport') }
